function main(config) {
  if (!config.proxies) config.proxies = [];

  config.ipv6 = false;

  const NODIRECT = "^((?!(直连|DIRECT)).)*$";
  const NOJUNK = "剩余|流量|到期|过期|官网|订阅|重置|续费|Traffic|Expire|GB";

  const HC_URL = "https://www.gstatic.com/generate_204";
  const HC_INT = 300;

  const ICON = "https://raw.githubusercontent.com/RiverFlowsInUUU/self-conf/main/icons/";
  const RAW = "https://raw.githubusercontent.com/RiverFlowsInUUU/self-conf/main/";
  const JS = "https://cdn.jsdelivr.net/gh/MetaCubeX/meta-rules-dat@meta/geo";

  const HAS_PROVIDERS =
    config["proxy-providers"] && Object.keys(config["proxy-providers"]).length > 0;
  const ALL_KEY = HAS_PROVIDERS ? "include-all" : "include-all-proxies";
  const allNodes = {};
  allNodes[ALL_KEY] = true;

  config["proxy-groups"] = [
    {
      name: "Proxy",
      type: "url-test",
      ...allNodes,
      filter: NODIRECT,
      "exclude-filter": NOJUNK,
      url: HC_URL,
      interval: HC_INT,
      tolerance: 50,
      icon: ICON + "Proxy.png",
    },
    {
      name: "AI",
      type: "select",
      proxies: ["Proxy"],
      ...allNodes,
      filter: NODIRECT,
      "exclude-filter": NOJUNK,
      icon: ICON + "grok.png",
    },
    {
      name: "AD",
      type: "select",
      proxies: ["REJECT"],
      icon: ICON + "AdBlock.png",
    },
  ];

  const rp = {};
  config["rule-providers"] = rp;

  [
    { n: "private", b: "domain" },
    { n: "cn", b: "domain" },
    { n: "category-ai-chat-!cn", b: "domain" },
  ].forEach(function (c) {
    rp[c.n] = {
      type: "http",
      behavior: c.b,
      format: "mrs",
      url: JS + "/geosite/" + c.n + ".mrs",
      path: "./rule_provider/" + c.n + ".mrs",
      interval: 86400,
    };
  });
  [
    { n: "private", b: "ipcidr" },
    { n: "cn", b: "ipcidr" },
  ].forEach(function (c) {
    rp["geoip-" + c.n] = {
      type: "http",
      behavior: c.b,
      format: "mrs",
      url: JS + "/geoip/" + c.n + ".mrs",
      path: "./rule_provider/geoip-" + c.n + ".mrs",
      interval: 86400,
    };
  });

  rp["AWAvenue-Ads"] = {
    type: "http",
    behavior: "domain",
    format: "mrs",
    url: "https://raw.githubusercontent.com/TG-Twilight/AWAvenue-Ads-Rule/main/Filters/AWAvenue-Ads-Rule-Clash.mrs",
    path: "./rule_provider/AWAvenue-Ads-Rule-Clash.mrs",
    interval: 86400,
  };

  rp["Jinx-CN"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: "https://raw.githubusercontent.com/RiverFlowsInUUU/RFU-Rules/main/mihomo-direct.yaml",
    path: "./rule_provider/Jinx-CN.yaml",
    interval: 86400,
  };
  rp["Jinx-Ads"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: "https://raw.githubusercontent.com/RiverFlowsInUUU/RFU-Rules/main/mihomo-ads.yaml",
    path: "./rule_provider/Jinx-Ads.yaml",
    interval: 86400,
  };

  rp["AI_Domains"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: RAW + "rules/AI_Domains.yaml",
    path: "./rule_provider/AI_Domains.yaml",
    interval: 86400,
  };
  rp["apple-system"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: RAW + "rules/apple_system.yaml",
    path: "./rule_provider/apple_system.yaml",
    interval: 86400,
  };

  config.rules = [
    "RULE-SET,Jinx-CN,DIRECT",
    "RULE-SET,Jinx-Ads,AD",
    "RULE-SET,AWAvenue-Ads,AD",
    "RULE-SET,apple-system,DIRECT",
    "RULE-SET,geoip-private,DIRECT,no-resolve",
    "RULE-SET,private,DIRECT",
    "RULE-SET,category-ai-chat-!cn,AI",
    "RULE-SET,AI_Domains,AI",
    "DOMAIN-SUFFIX,xn--ngstr-lra8j.com,Proxy",
    "DOMAIN-SUFFIX,services.googleapis.cn,Proxy",
    "RULE-SET,cn,DIRECT",
    "RULE-SET,geoip-cn,DIRECT,no-resolve",
    "MATCH,Proxy",
  ];

  config.dns = {
    enable: true,
    ipv6: false,
    "enhanced-mode": "fake-ip",
    "fake-ip-range": "198.18.0.1/16",
    "respect-rules": true,
    "use-hosts": true,
    "use-system-hosts": false,
    "prefer-h3": false,

    "default-nameserver": ["223.5.5.5", "119.29.29.29"],
    "proxy-server-nameserver": [
      "https://223.5.5.5/dns-query",
      "https://120.53.53.53/dns-query",
    ],
    "direct-nameserver": [
      "https://223.5.5.5/dns-query",
      "https://120.53.53.53/dns-query",
    ],
    nameserver: [
      "https://1.1.1.1/dns-query",
      "https://8.8.8.8/dns-query",
    ],

    "nameserver-policy": {
      "rule-set:AWAvenue-Ads": "rcode://success",
      "rule-set:Jinx-Ads": "rcode://success",
      "rule-set:private": [
        "https://223.5.5.5/dns-query",
        "https://120.53.53.53/dns-query",
      ],
      "rule-set:cn": [
        "https://223.5.5.5/dns-query",
        "https://120.53.53.53/dns-query",
      ],
    },

    "fake-ip-filter": [
      "*.lan",
      "*.local",
      "*.localdomain",
      "*.home.arpa",
      "+.msftconnecttest.com",
      "+.msftncsi.com",
      "localhost.ptlogin2.qq.com",
      "+.srv.nintendo.net",
      "+.stun.playstation.net",
      "+.xboxlive.com",
      "stun.*",
      "time.*.com",
      "ntp.*.com",
      "+.pool.ntp.org",
      "+.market.xiaomi.com",
      "rule-set:AWAvenue-Ads",
      "rule-set:Jinx-Ads",
    ],
  };

  return config;
}
